<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Snake</title>
<style>
  :root{
    --bg:#0b0f14;
    --panel:#131a22;
    --ink:#e6edf3;
    --muted:#8b98a5;
    --accent:#4ade80;
    --accent2:#22d3ee;
    --danger:#f87171;
  }
  *{box-sizing:border-box}
  html,body{height:100%}
  body{
    margin:0;
    background:
      radial-gradient(1200px 600px at 50% -10%, #16222e 0%, rgba(11,15,20,0) 70%),
      var(--bg);
    color:var(--ink);
    font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
    display:flex;
    align-items:center;
    justify-content:center;
    padding:24px 16px;
    min-height:100%;
  }
  .wrap{
    width:min(560px,100%);
    display:flex;
    flex-direction:column;
    align-items:center;
    gap:14px;
  }
  h1{
    margin:0;
    font-size:26px;
    letter-spacing:.22em;
    text-transform:uppercase;
    font-weight:700;
    background:linear-gradient(90deg,var(--accent),var(--accent2));
    -webkit-background-clip:text;
    background-clip:text;
    color:transparent;
  }
  .hud{
    width:100%;
    display:flex;
    align-items:center;
    justify-content:space-between;
    gap:12px;
    background:var(--panel);
    border:1px solid #223040;
    border-radius:12px;
    padding:10px 14px;
    box-shadow:0 6px 22px rgba(0,0,0,.35);
  }
  .stat{display:flex;align-items:baseline;gap:8px}
  .stat .label{
    font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted);
  }
  #score{
    font-size:24px;font-weight:800;font-variant-numeric:tabular-nums;color:var(--accent);
    min-width:2ch;text-align:right;
  }
  #best{font-size:16px;font-weight:700;color:var(--muted);font-variant-numeric:tabular-nums}
  #status{font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}
  .board-shell{
    position:relative;
    padding:10px;
    border-radius:16px;
    background:linear-gradient(160deg,#1b2735,#101720);
    border:1px solid #24344a;
    box-shadow:0 18px 50px rgba(0,0,0,.5), inset 0 1px 0 rgba(255,255,255,.04);
  }
  #snake{
    display:block;
    width:480px;
    height:480px;
    max-width:min(80vw,480px);
    max-height:min(80vw,480px);
    border-radius:10px;
    background:#0d141c;
    touch-action:none;
  }
  @media (max-width:520px){ #snake{width:400px;height:400px;max-width:100%;max-height:none} }
  .controls{display:flex;gap:10px;flex-wrap:wrap;justify-content:center}
  button{
    appearance:none;
    border:1px solid #2b3c50;
    background:#18222e;
    color:var(--ink);
    font:inherit;
    font-size:14px;
    font-weight:600;
    letter-spacing:.05em;
    padding:10px 20px;
    border-radius:10px;
    cursor:pointer;
    transition:transform .08s ease, background .15s ease, border-color .15s ease;
  }
  button:hover{background:#1f2c3a;border-color:#3a5170}
  button:active{transform:translateY(1px)}
  button:focus-visible{outline:2px solid var(--accent2);outline-offset:2px}
  #start{border-color:#2f6b47;background:#16301f}
  #start:hover{background:#1b3d27}
  #reset{border-color:#5b2b2b;background:#2a1717}
  #reset:hover{background:#361c1c}
  .hint{color:var(--muted);font-size:12px;text-align:center;line-height:1.6}
  kbd{
    background:#1d2835;border:1px solid #33465c;border-bottom-width:2px;
    border-radius:5px;padding:1px 5px;font-family:inherit;font-size:11px;color:#cbd5e1;
  }
</style>
</head>
<body>
<div class="wrap">
  <h1>Snake</h1>

  <div class="hud">
    <div class="stat"><span class="label">Score</span><span id="score">0</span></div>
    <div id="status">Press Start</div>
    <div class="stat"><span class="label">Best</span><span id="best">0</span></div>
  </div>

  <div class="board-shell">
    <canvas id="snake" width="480" height="480" aria-label="Snake game board"></canvas>
  </div>

  <div class="controls">
    <button id="start" type="button">Start</button>
    <button id="pause" type="button">Pause</button>
    <button id="reset" type="button">Reset</button>
  </div>

  <p class="hint">
    Steer with <kbd>←</kbd> <kbd>↑</kbd> <kbd>→</kbd> <kbd>↓</kbd> &nbsp;·&nbsp; <kbd>Space</kbd> start / pause &nbsp;·&nbsp; <kbd>R</kbd> reset
  </p>
</div>

<script>
(function(){
  "use strict";

  /* ---------------- config ---------------- */
  const W = 20;              // cells across (>= 10)
  const H = 20;              // cells down   (>= 10)
  const CSS_SIZE = 480;      // CSS pixels (>= 400)
  const BASE_SPEED = 120;    // ms per tick
  const MIN_SPEED  = 60;

  const DIRS = {
    up:    [0,-1],
    down:  [0, 1],
    left:  [-1,0],
    right: [1, 0]
  };
  const OPP = { up:'down', down:'up', left:'right', right:'left' };

  /* ---------------- state ---------------- */
  let snakeCells = [];
  let dir = 'right';
  let pendingDir = null;
  let foodCell = null;
  let isAlive = true;
  let scoreVal = 0;
  let best = 0;
  let timer = null;
  let flash = 0;   // eat animation counter
  let frame = 0;

  /* ---------------- canvas ---------------- */
  const canvas = document.getElementById('snake');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const bestEl = document.getElementById('best');
  const statusEl = document.getElementById('status');

  let cell = CSS_SIZE / W; // logical (CSS) cell size
  function setupCanvas(){
    const dpr = Math.max(1, Math.min(3, window.devicePixelRatio || 1));
    canvas.style.width  = CSS_SIZE + 'px';
    canvas.style.height = CSS_SIZE + 'px';
    canvas.width  = Math.round(CSS_SIZE * dpr);
    canvas.height = Math.round(CSS_SIZE * dpr);
    ctx.setTransform(dpr,0,0,dpr,0,0);
    cell = CSS_SIZE / W;
  }
  setupCanvas();

  /* ---------------- helpers ---------------- */
  function eq(a,b){ return a[0]===b[0] && a[1]===b[1]; }

  function occupied(x,y){
    for(let i=0;i<snakeCells.length;i++){
      if(snakeCells[i][0]===x && snakeCells[i][1]===y) return true;
    }
    return false;
  }

  function freeCells(){
    const out = [];
    for(let y=0;y<H;y++)
      for(let x=0;x<W;x++)
        if(!occupied(x,y)) out.push([x,y]);
    return out;
  }

  function spawnFood(){
    const free = freeCells();
    if(!free.length){ foodCell = null; return; }
    foodCell = free[Math.floor(Math.random()*free.length)].slice();
  }

  function setStatus(txt){ statusEl.textContent = txt; }
  function renderScore(){
    scoreEl.textContent = String(scoreVal);
    if(scoreVal > best){ best = scoreVal; }
    bestEl.textContent = String(best);
  }

  function speedForScore(){
    return Math.max(MIN_SPEED, BASE_SPEED - scoreVal * 3);
  }

  /* ---------------- core game ---------------- */
  function reset(){
    const cy = Math.floor(H/2);
    const cx = Math.floor(W/2);
    snakeCells = [[cx,cy],[cx-1,cy],[cx-2,cy]]; // head first, length 3
    dir = 'right';
    pendingDir = null;
    isAlive = true;
    scoreVal = 0;
    flash = 0;
    spawnFood();
    renderScore();
    draw();
    return true;
  }

  function setDir(d){
    if(!DIRS[d]) return false;
    if(d === dir) { pendingDir = d; return true; }
    if(OPP[dir] === d) return false;   // 180 degree reversal -> ignored
    pendingDir = d;
    return true;
  }

  function tick(){
    if(!isAlive) return false;

    if(pendingDir && OPP[dir] !== pendingDir){ dir = pendingDir; }
    pendingDir = null;

    const d = DIRS[dir];
    const head = snakeCells[0];
    const nx = head[0] + d[0];
    const ny = head[1] + d[1];

    // wall
    if(nx < 0 || ny < 0 || nx >= W || ny >= H){
      die();
      return false;
    }

    const ate = !!(foodCell && foodCell[0] === nx && foodCell[1] === ny);

    // self collision (the tail cell vacates unless we grow)
    const last = snakeCells.length - 1;
    for(let i=0;i<snakeCells.length;i++){
      if(!ate && i === last) continue;
      if(snakeCells[i][0] === nx && snakeCells[i][1] === ny){
        die();
        return false;
      }
    }

    snakeCells.unshift([nx,ny]);
    if(ate){
      scoreVal += 1;
      flash = 6;
      renderScore();
      spawnFood();
      if(timer) restartTimer();
    } else {
      snakeCells.pop();
    }

    draw();
    return true;
  }

  function die(){
    isAlive = false;
    stopTimer();
    setStatus('Game Over');
    draw();
  }

  /* ---------------- loop control ---------------- */
  function restartTimer(){
    stopTimer();
    timer = setInterval(tick, speedForScore());
  }
  function start(){
    if(!isAlive) reset();
    if(timer) return;
    restartTimer();
    setStatus('Playing');
  }
  function stopTimer(){
    if(timer){ clearInterval(timer); timer = null; }
  }
  function pause(){
    if(!timer) return;
    stopTimer();
    if(isAlive) setStatus('Paused');
  }
  function fullReset(){
    stopTimer();
    reset();
    setStatus('Press Start');
  }

  /* ---------------- drawing ---------------- */
  function roundRect(x,y,w,h,r){
    const rr = Math.min(r, w/2, h/2);
    ctx.beginPath();
    ctx.moveTo(x+rr,y);
    ctx.lineTo(x+w-rr,y);
    ctx.quadraticCurveTo(x+w,y,x+w,y+rr);
    ctx.lineTo(x+w,y+h-rr);
    ctx.quadraticCurveTo(x+w,y+h,x+w-rr,y+h);
    ctx.lineTo(x+rr,y+h);
    ctx.quadraticCurveTo(x,y+h,x,y+h-rr);
    ctx.lineTo(x,y+rr);
    ctx.quadraticCurveTo(x,y,x+rr,y);
    ctx.closePath();
  }

  function draw(){
    frame++;
    // background
    ctx.clearRect(0,0,CSS_SIZE,CSS_SIZE);
    ctx.fillStyle = '#0d141c';
    ctx.fillRect(0,0,CSS_SIZE,CSS_SIZE);

    // checkerboard
    for(let y=0;y<H;y++){
      for(let x=0;x<W;x++){
        if((x+y)%2===0) continue;
        ctx.fillStyle = 'rgba(255,255,255,0.022)';
        ctx.fillRect(x*cell, y*cell, cell, cell);
      }
    }
    // border glow
    ctx.strokeStyle = 'rgba(74,222,128,0.18)';
    ctx.lineWidth = 2;
    ctx.strokeRect(1,1,CSS_SIZE-2,CSS_SIZE-2);

    // food
    if(foodCell){
      const pulse = 1 + 0.07*Math.sin(frame/3);
      const cx = foodCell[0]*cell + cell/2;
      const cy = foodCell[1]*cell + cell/2;
      const r = (cell*0.32) * pulse;
      const g = ctx.createRadialGradient(cx-r*0.3, cy-r*0.35, r*0.15, cx, cy, r*1.6);
      g.addColorStop(0,'#ffd7d7');
      g.addColorStop(0.45,'#f87171');
      g.addColorStop(1,'rgba(248,113,113,0.05)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(cx,cy,r*1.55,0,Math.PI*2);
      ctx.fill();
      ctx.fillStyle = '#ef4444';
      ctx.beginPath();
      ctx.arc(cx,cy,r,0,Math.PI*2);
      ctx.fill();
      ctx.fillStyle = 'rgba(255,255,255,0.75)';
      ctx.beginPath();
      ctx.arc(cx-r*0.32, cy-r*0.35, Math.max(1,r*0.22),0,Math.PI*2);
      ctx.fill();
    }

    // snake body (tail -> head so head is drawn last)
    const n = snakeCells.length;
    for(let i=n-1;i>=0;i--){
      const s = snakeCells[i];
      const t = n>1 ? i/(n-1) : 0;
      const light = 62 - t*24;
      const hue = 148 - t*18;
      const inset = i===0 ? cell*0.06 : cell*0.12 + t*cell*0.05;
      ctx.fillStyle = isAlive ? 'hsl('+hue+',65%,'+light+'%)' : 'hsl(0,35%,'+(light-12)+'%)';
      if(i===0 && flash>0){ ctx.fillStyle = '#eafff2'; }
      roundRect(s[0]*cell+inset, s[1]*cell+inset, cell-inset*2, cell-inset*2, cell*0.32);
      ctx.fill();
      if(i===0){
        // eyes
        const d = DIRS[dir];
        const cx = s[0]*cell + cell/2;
        const cy = s[1]*cell + cell/2;
        const off = cell*0.19;
        const fx = d[0]*cell*0.18, fy = d[1]*cell*0.18;
        const px = d[0]===0 ? off : 0;
        const py = d[1]===0 ? off : 0;
        ctx.fillStyle = '#08121a';
        ctx.beginPath(); ctx.arc(cx+fx+px, cy+fy+py, Math.max(1.2,cell*0.085),0,Math.PI*2); ctx.fill();
        ctx.beginPath(); ctx.arc(cx+fx-px, cy+fy-py, Math.max(1.2,cell*0.085),0,Math.PI*2); ctx.fill();
      }
    }
    if(flash>0) flash--;

    // overlays
    if(!isAlive){
      ctx.fillStyle = 'rgba(8,12,18,0.66)';
      ctx.fillRect(0,0,CSS_SIZE,CSS_SIZE);
      ctx.textAlign = 'center';
      ctx.fillStyle = '#f87171';
      ctx.font = '700 34px ui-sans-serif,system-ui,sans-serif';
      ctx.fillText('GAME OVER', CSS_SIZE/2, CSS_SIZE/2 - 6);
      ctx.fillStyle = '#cbd5e1';
      ctx.font = '600 15px ui-sans-serif,system-ui,sans-serif';
      ctx.fillText('Score ' + scoreVal + ' — press Reset or Start', CSS_SIZE/2, CSS_SIZE/2 + 26);
    } else if(!timer){
      ctx.textAlign = 'center';
      ctx.fillStyle = 'rgba(203,213,225,0.75)';
      ctx.font = '600 14px ui-sans-serif,system-ui,sans-serif';
      ctx.fillText('Press Start / Space', CSS_SIZE/2, CSS_SIZE - 14);
    }
  }

  /* ---------------- input ---------------- */
  const KEYMAP = {
    ArrowUp:'up', ArrowDown:'down', ArrowLeft:'left', ArrowRight:'right',
    w:'up', s:'down', a:'left', d:'right',
    W:'up', S:'down', A:'left', D:'right'
  };
  window.addEventListener('keydown', function(e){
    const d = KEYMAP[e.key];
    if(d){
      e.preventDefault();
      setDir(d);
      if(!timer && isAlive) start();
      else if(!timer) draw();
      return;
    }
    if(e.key === ' '){
      e.preventDefault();
      if(timer) pause(); else start();
    } else if(e.key === 'r' || e.key === 'R'){
      e.preventDefault();
      fullReset();
    }
  }, {passive:false});

  document.getElementById('start').addEventListener('click', start);
  document.getElementById('pause').addEventListener('click', pause);
  document.getElementById('reset').addEventListener('click', fullReset);

  // swipe support
  let touchStart = null;
  canvas.addEventListener('touchstart', function(e){
    const t = e.changedTouches[0];
    touchStart = [t.clientX, t.clientY];
  }, {passive:true});
  canvas.addEventListener('touchend', function(e){
    if(!touchStart) return;
    const t = e.changedTouches[0];
    const dx = t.clientX - touchStart[0], dy = t.clientY - touchStart[1];
    if(Math.abs(dx) > Math.abs(dy)) setDir(dx > 0 ? 'right' : 'left');
    else setDir(dy > 0 ? 'down' : 'up');
    touchStart = null;
    if(!timer) start();
  }, {passive:true});

  window.addEventListener('blur', pause);

  /* ---------------- public API ---------------- */
  window.game = {
    w: W,
    h: H,
    cols: W,
    rows: H,
    reset: function(){ stopTimer(); reset(); setStatus('Press Start'); },
    tick: function(){ return tick(); },
    setDir: function(d){ return setDir(d); },
    setFood: function(x,y){
      x = Math.max(0, Math.min(W-1, x|0));
      y = Math.max(0, Math.min(H-1, y|0));
      foodCell = [x,y];
      draw();
      return foodCell.slice();
    },
    snake: function(){ return snakeCells.map(function(c){ return [c[0], c[1]]; }); },
    food: function(){ return foodCell ? [foodCell[0], foodCell[1]] : [-1,-1]; },
    alive: function(){ return isAlive; },
    score: function(){ return scoreVal; },
    start: start,
    pause: pause,
    isRunning: function(){ return !!timer; }
  };

  reset();
  setStatus('Press Start');
})();
</script>
</body>
</html>
